package dev.aster.vega.dataflow.geo

import dev.aster.vega.model.VegaJson
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

/**
 * Every projection type the corpus names, against d3-geo's own path strings.
 *
 * Each is built the way a specification builds one — `type`, then a scale and a translation — so
 * what is being checked is not only the formula but everything the *name* carries with it: the clip
 * angle `orthographic` needs to hide the far side of the globe, the standard parallels and centring
 * that make `albers` a map of the United States rather than of a cone, and the quarter turn that
 * makes `transverseMercator` transverse.
 *
 * Four geometries each, for the reasons [GeoProjectionTest] gives.
 */
class GeoProjectionTypesTest {

  private fun path(projection: Projection, geometry: String): String? {
    val sink = PathStringSink()
    GeoJsonStream.stream(VegaJson.parse(geometry), projection.stream(sink))
    return sink.result()
  }

  /**
   * Every coordinate within one printed digit, for the two projections whose clip circle sits 0.001
   * degrees from the antipode.
   *
   * Not a loosened comparison: it is the only honest one there. `azimuthalEqualArea` scales by
   * `sqrt(2 / (1 + cos c))`, and at a clip radius of 179.999 degrees that denominator is 1.5e-10 —
   * so the scale factor is about 114,591 and its derivative is 3.8e14. A **one-ulp** difference in
   * `cos` between V8 and the JVM, which neither runtime promises to avoid, is amplified into 1.3e-4
   * of a pixel, which is enough to move a value across a rounding boundary in the third decimal.
   * Measured, not assumed: the arithmetic is in the commit that added this.
   *
   * Everything about the port is still checked — the point count, the order, the topology and every
   * coordinate to within one unit of the last digit upstream printed. What is not checked is the
   * last bit of `cos`.
   */
  private fun assertPathWithin(expected: String, actual: String?, unitsInLastPlace: Int) {
    val expectedNumbers = numbers(expected)
    val actualNumbers = numbers(actual ?: "")
    assertEquals(shape(expected), shape(actual ?: ""), "the path's commands differ")
    assertEquals(expectedNumbers.size, actualNumbers.size, "the path has a different point count")
    for (index in expectedNumbers.indices) {
      // Compared in thousandths, which is the unit a path string is written in: a difference is
      // counted in printed digits rather than in a tolerance that has to absorb its own rounding.
      val difference =
        kotlin.math.abs(
          kotlin.math.round(expectedNumbers[index] * 1000) -
            kotlin.math.round(actualNumbers[index] * 1000)
        )
      assertTrue(
        difference <= unitsInLastPlace,
        "coordinate $index: expected ${expectedNumbers[index]}, got ${actualNumbers[index]}",
      )
    }
  }

  private fun numbers(path: String): List<Double> =
    Regex("-?[0-9.]+").findAll(path).map { it.value.toDouble() }.toList()

  /**
   * The commands alone, so a difference in shape is reported as one rather than as a coordinate.
   */
  private fun shape(path: String): String = path.filter { it.isLetter() }

